import osimport requests# ---- Config ----LLM_MODE = os.environ.get("LLM_MODE", "CLOUD")   # CLOUD | OFFOPENAI_MODEL = os.environ.get("OPENAI_MODEL", "gpt-4o-mini")OPENAI_API_KEY = os.environ.get("OPENAI_API_KEY")# ---- Prompt builder ----def _grounded_specimen_prompt(standard_id, version, specimen_id, lot, checks_table: str):    system = "You are a compliance QA assistant. Use ONLY the provided results."    user = f"""Standard: {standard_id} v{version}Specimen: {specimen_id}; Lot: {lot}Checks:{checks_table}Write:1) One-sentence PASS/FAIL summary naming the key failing/passing metric(s).2) Two concise remediation tips (process or test parameters).Under 80 words. No extra claims beyond the numbers above."""    return system, user# ---- Cloud completion ----def _cloud_complete(system: str, user: str) -> str:    if not OPENAI_API_KEY:        return "LLM unavailable (no API key). See numeric checks above."    url = "https://api.openai.com/v1/chat/completions"    headers = {"Authorization": f"Bearer {OPENAI_API_KEY}", "Content-Type": "application/json"}    payload = {        "model": OPENAI_MODEL,        "messages": [            {"role": "system", "content": system},            {"role": "user", "content": user}        ],        "temperature": 0.2,        "max_tokens": 250    }    r = requests.post(url, headers=headers, json=payload, timeout=60)    if r.status_code == 429:        return "Rate limit reached. Showing numeric checks only.\n• Improve failing metric toward threshold.\n• Re-test under specified method."    r.raise_for_status()    return r.json()["choices"][0]["message"]["content"].strip()# ---- Public API ----def explain_specimen(standard_id, version, specimen_id, lot, checks_table: str) -> str:    system, user = _grounded_specimen_prompt(standard_id, version, specimen_id, lot, checks_table)    if LLM_MODE.upper() == "OFF":        return "Summary: see numeric checks.\n• Improve the failing metric toward its threshold.\n• Re-test under specified method settings."    return _cloud_complete(system, user)